#!/bin/bash
set -e
dnf install -y nodejs22 nodejs22-npm || dnf install -y nodejs npm
mkdir -p /opt/app
echo '' | base64 -d | gunzip > /opt/app/app.js
echo '' | base64 -d > /opt/app/package.json
cd /opt/app
npm install --omit=dev

cat > /etc/systemd/system/uploader.service <<'SERVICE'
[Unit]
Description=uploader Resume Builder App
After=network-online.target
Wants=network-online.target

[Service]
Environment=BUCKET_NAME=itmo-444-544-jhan38-fileshare
Environment=AWS_REGION=us-east-2
Environment=PORT=3000
Environment=VIEWER_PORT=8081
Environment=GEMINI_KEY_PARAM=/itmo-444/gemini-api-key
Environment=GEMINI_MODEL=gemini-3.1-flash-lite
WorkingDirectory=/opt/app
ExecStart=/usr/bin/node /opt/app/app.js
Restart=always
RestartSec=5
User=ec2-user

[Install]
WantedBy=multi-user.target
SERVICE

chown -R ec2-user:ec2-user /opt/app
systemctl daemon-reload
systemctl enable --now uploader.service
